class Solution {
public:
    string convertDateToBinary(string date) {
        auto bin = [](long long x) {
            string r;
            do { r = char('0' + (x & 1)) + r; x >>= 1; } while (x);
            return r;
        };
        int y = stoi(date.substr(0, 4)), m = stoi(date.substr(5, 2)), d = stoi(date.substr(8, 2));
        return bin(y) + "-" + bin(m) + "-" + bin(d);
    }
};

