class Solution {
    private String b(int x) { StringBuilder sb = new StringBuilder(); do { sb.append(x & 1); x >>= 1; } while (x > 0); return sb.reverse().toString(); }
    public String convertDateToBinary(String date) {
        return b(Integer.parseInt(date.substring(0,4))) + "-" + b(Integer.parseInt(date.substring(5,7))) + "-" + b(Integer.parseInt(date.substring(8,10)));
    }
}

